contracts/DFLIX.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DFLIX
 * @author Decentralflix — Phase 2
 * @notice The Decentralflix ERC20 token ("Decentralflix", symbol DFLIX, 18 decimals).
 *
 * Capabilities:
 * - Capped minting: accounts with MINTER_ROLE (granted by the admin) can mint,
 *   but total supply can never exceed MAX_SUPPLY (1,000,000,000 DFLIX).
 * - Staking: holders stake DFLIX for a minimum lock period (7 days) and accrue
 *   rewards from a reward pool at an admin-set rate.
 * - Seed-to-earn: the owner/attestor allocates rewards to seeders against
 *   off-chain seeding reports (identified by reportHash, replay-protected);
 *   seeders claim through the same claimRewards() path.
 *
 * ══════════════════════════════════════════════════════════════════════════
 *  REWARDS ARE PROTOCOL MECHANICS — NOT PROMISED YIELD.
 *  Staking rewards and seed-to-earn allocations are variable, pool-limited,
 *  and paid ONLY from the funded reward pool. Nothing here is a promise of
 *  yield, interest, profit, or any return on any contribution. The reward
 *  rate can be changed or set to zero by the admin at any time, the pool can
 *  run dry, and unclaimed accruals are bounded by what the pool holds.
 *  ANY MAINNET DEPLOYMENT MUST BE REVIEWED BY LICENSED COUNSEL FIRST
 *  (securities/Howey analysis, money-transmitter, tax, and consumer-law
 *  implications). This contract is provided for development/testing.
 * ══════════════════════════════════════════════════════════════════════════
 */
contract DFLIX is ERC20, AccessControl, ReentrancyGuard {
    /// @notice Role allowed to mint new tokens (granted/revoked by the admin).
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @notice Absolute mint cap: 1 billion DFLIX (18 decimals).
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 1e18;

    /// @notice Minimum time between a user's first stake and any unstake.
    uint256 public constant STAKE_LOCK_PERIOD = 7 days;

    /// @notice Staking reward rate: DFLIX per second per staked DFLIX, scaled by 1e18.
    /// E.g. 1e12 => 1e-6 DFLIX per staked DFLIX per second. Admin-settable, may be 0.
    uint256 public rewardPerTokenPerSecond;

    /// @notice DFLIX funded into the reward pool and not yet paid out.
    uint256 public rewardPool;

    /// @notice Address (besides the admin) allowed to allocate seed rewards.
    address public attestor;

    // Staking state
    mapping(address => uint256) public stakedBalance; // user => staked DFLIX
    mapping(address => uint256) public stakeLockStart; // user => first-stake timestamp
    mapping(address => uint256) private _rewardLastUpdate; // user => last accrual checkpoint
    mapping(address => uint256) private _accruedRewards; // user => checkpointed staking rewards

    // Seed-to-earn state
    mapping(address => uint256) public seedRewards; // seeder => allocated, unclaimed
    mapping(bytes32 => bool) public usedReportHashes; // reportHash => already allocated (replay guard)
    uint256 public allocatedSeedRewards; // total seed rewards allocated but not yet claimed

    // ── Errors ────────────────────────────────────────────────────────────
    error ExceedsMintCap(uint256 requested, uint256 maxSupply);
    error ZeroAmount();
    error ZeroAddress();
    error NotAuthorized(address caller);
    error InsufficientStake(uint256 requested, uint256 staked);
    error StakeLocked(uint256 unlockAt, uint256 nowTs);
    error NoRewardsToClaim(address user);
    error InsufficientRewardPool(uint256 needed, uint256 available);
    error DuplicateReport(bytes32 reportHash);

    // ── Events ────────────────────────────────────────────────────────────
    event RewardPoolFunded(address indexed funder, uint256 amount);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);
    event AttestorUpdated(address indexed oldAttestor, address indexed newAttestor);
    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(
        address indexed user,
        uint256 total,
        uint256 stakingPart,
        uint256 seedPart
    );
    event SeedRewardAllocated(
        address indexed seeder,
        uint256 amount,
        bytes32 indexed reportHash
    );

    constructor() ERC20("Decentralflix", "DFLIX") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        attestor = msg.sender;
    }

    modifier onlyAdminOrAttestor() {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender) && msg.sender != attestor) {
            revert NotAuthorized(msg.sender);
        }
        _;
    }

    // ── Minting ───────────────────────────────────────────────────────────

    /**
     * @notice Mint new DFLIX. Only callable by MINTER_ROLE; reverts if the mint
     * would push total supply above MAX_SUPPLY.
     */
    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (totalSupply() + amount > MAX_SUPPLY) {
            revert ExceedsMintCap(totalSupply() + amount, MAX_SUPPLY);
        }
        _mint(to, amount);
    }

    // ── Admin ─────────────────────────────────────────────────────────────

    /// @notice Replace the attestor allowed to allocate seed rewards.
    function setAttestor(address newAttestor) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newAttestor == address(0)) revert ZeroAddress();
        address oldAttestor = attestor;
        attestor = newAttestor;
        emit AttestorUpdated(oldAttestor, newAttestor);
    }

    /**
     * @notice Set the staking reward rate (per-second, 1e18-scaled). May be set
     * to zero to stop new staking accrual (NOT a yield promise — see header).
     */
    function setRewardRate(uint256 newRate) external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 oldRate = rewardPerTokenPerSecond;
        rewardPerTokenPerSecond = newRate;
        emit RewardRateUpdated(oldRate, newRate);
    }

    /**
     * @notice Fund the reward pool. Moves `amount` DFLIX from the admin's own
     * balance into the contract. No allowance is needed: the token contract
     * moves balances internally and the caller is explicitly depositing their
     * own tokens. Rewards can only ever be paid out of this pool.
     */
    function fundRewardPool(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (amount == 0) revert ZeroAmount();
        rewardPool += amount;
        _transfer(msg.sender, address(this), amount);
        emit RewardPoolFunded(msg.sender, amount);
    }

    // ── Seed-to-earn ──────────────────────────────────────────────────────

    /**
     * @notice Allocate seed-to-earn rewards to a seeder against an off-chain
     * seeding report. Replay-protected by `reportHash`, and the total allocated
     * seed rewards can never exceed the funded pool (best-effort guard —
     * staking accruals are not pre-reserved against the pool).
     * @dev The seeder claims via claimRewards(). This is a protocol mechanic,
     * NOT promised yield (see header notice).
     */
    function allocateSeedReward(
        address seeder,
        uint256 amount,
        bytes32 reportHash
    ) external onlyAdminOrAttestor {
        if (seeder == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (usedReportHashes[reportHash]) revert DuplicateReport(reportHash);
        if (allocatedSeedRewards + amount > rewardPool) {
            revert InsufficientRewardPool(allocatedSeedRewards + amount, rewardPool);
        }

        usedReportHashes[reportHash] = true;
        allocatedSeedRewards += amount;
        seedRewards[seeder] += amount;

        emit SeedRewardAllocated(seeder, amount, reportHash);
    }

    // ── Staking ──────────────────────────────────────────────────────────

    /**
     * @notice Stake DFLIX. Moves tokens from the caller's balance into the
     * contract (no allowance needed — the caller explicitly deposits their own
     * tokens). First stake starts the user's lock clock; further stakes do not
     * extend it.
     * @dev Accrues pending staking rewards up to this point before updating
     * the balance, so partial unstakes don't over-count.
     */
    function stake(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        _checkpoint(msg.sender);

        if (stakeLockStart[msg.sender] == 0) {
            stakeLockStart[msg.sender] = block.timestamp;
        }
        stakedBalance[msg.sender] += amount;

        _transfer(msg.sender, address(this), amount);

        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Unstake DFLIX. Blocked until STAKE_LOCK_PERIOD has passed since
     * the user's first stake. Pending staking rewards stay claimable via
     * claimRewards().
     */
    function unstake(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        uint256 staked = stakedBalance[msg.sender];
        if (amount > staked) revert InsufficientStake(amount, staked);

        uint256 unlockAt = stakeLockStart[msg.sender] + STAKE_LOCK_PERIOD;
        if (block.timestamp < unlockAt) revert StakeLocked(unlockAt, block.timestamp);

        _checkpoint(msg.sender);
        stakedBalance[msg.sender] = staked - amount;
        if (stakedBalance[msg.sender] == 0) {
            stakeLockStart[msg.sender] = 0;
        }

        _transfer(address(this), msg.sender, amount);

        emit Unstaked(msg.sender, amount);
    }

    /**
     * @notice Claim all pending rewards (accrued staking rewards + allocated
     * seed rewards) in one transfer. Reverts when there is nothing to claim or
     * when the pool cannot cover the claim.
     * @dev Rewards are protocol mechanics, NOT promised yield — see header.
     */
    function claimRewards() external nonReentrant {
        _checkpoint(msg.sender);

        uint256 stakingPart = _accruedRewards[msg.sender];
        uint256 seedPart = seedRewards[msg.sender];
        uint256 total = stakingPart + seedPart;
        if (total == 0) revert NoRewardsToClaim(msg.sender);
        if (total > rewardPool) revert InsufficientRewardPool(total, rewardPool);

        _accruedRewards[msg.sender] = 0;
        seedRewards[msg.sender] = 0;
        allocatedSeedRewards -= seedPart;
        rewardPool -= total;

        _transfer(address(this), msg.sender, total);

        emit RewardsClaimed(msg.sender, total, stakingPart, seedPart);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /**
     * @notice Pending rewards for `user`: checkpointed staking rewards plus
     * live accrual since the last checkpoint, plus unclaimed seed rewards.
     */
    function pendingRewards(address user)
        external
        view
        returns (
            uint256 stakingPart,
            uint256 seedPart,
            uint256 total
        )
    {
        stakingPart = _accruedRewards[user];
        uint256 staked = stakedBalance[user];
        if (staked > 0 && rewardPerTokenPerSecond > 0) {
            uint256 elapsed = block.timestamp - _rewardLastUpdate[user];
            stakingPart += (staked * rewardPerTokenPerSecond * elapsed) / 1e18;
        }
        seedPart = seedRewards[user];
        total = stakingPart + seedPart;
    }

    /// @notice Checkpointed (not live-accrued) staking rewards for `user`.
    function accruedRewards(address user) external view returns (uint256) {
        return _accruedRewards[user];
    }

    /// @notice Last accrual checkpoint timestamp for `user`.
    function rewardLastUpdate(address user) external view returns (uint256) {
        return _rewardLastUpdate[user];
    }

    // ── Internal ──────────────────────────────────────────────────────────

    /**
     * @dev Rolls live staking accrual into _accruedRewards[user] and stamps the
     * checkpoint time. Called before every stake/unstake/claim.
     */
    function _checkpoint(address user) internal {
        uint256 staked = stakedBalance[user];
        if (staked > 0 && rewardPerTokenPerSecond > 0) {
            uint256 elapsed = block.timestamp - _rewardLastUpdate[user];
            if (elapsed > 0) {
                _accruedRewards[user] += (staked * rewardPerTokenPerSecond * elapsed) / 1e18;
            }
        }
        _rewardLastUpdate[user] = block.timestamp;
    }
}

contracts/FilmmakerCampaign.sol.content:
// SPDX-License-Identifier: MIT
// ============================================================================
// DEFERRED — DO NOT DEPLOY OR OFFER.
//
// This contract (FilmmakerCampaign) implements crowdfunding mechanics that
// are DEFERRED per the DecentralFlix research PDFs: offering crowdfunding
// without a registered funding portal risks an unregistered securities
// offering. It is retained for architecture and test history ONLY. It is not
// deployed by scripts/deploy.ts, the /crowdfund route shows a deferral
// notice, and no UI offers crowdfunding. Do not re-enable without Dino's
// explicit authorization and a compliant legal structure (registered funding
// portal + transaction-specific counsel).
// ============================================================================
pragma solidity ^0.8.20;

import "erc721a/contracts/ERC721A.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./MovieTicket.sol";

pragma solidity ^0.8.20;

import "erc721a/contracts/ERC721A.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./MovieTicket.sol";

/**
 * @title FilmmakerCampaign
 * @dev Decentralflix Crowdfunding + Milestone Escrow + InvestmentNFTs — UTILITY ONLY (HIGHEST LEGAL RISK AREA)
 *
 * CRITICAL LEGAL WARNING (Step 3 — user-provided research):
 * Producer-tier crowdfunding + milestone escrow + AI review windows create the highest exposure under Howey test.
 * - All InvestmentNFTs and backings are STRICTLY UTILITY/ACCESS tokens only.
 * - NO promises of returns, repayment, profits, or completion.
 * - Platform provides ZERO custody; funds live only in this contract's escrow.
 * - Milestone proofs submitted by Producer-tier backers have a mandatory 48-72h review window (non-custodial design).
 *
 * This contract must be read together with:
 * - docs/legal/ToS.md §4 (NFTs, Crowdfunding, Escrow)
 * - docs/legal/RESEARCH_AND_INTEGRATION.md (Howey + money transmission analysis)
 * - Clickwrap consent modal enforced in frontend before any launch/contribute/AI-proof action.
 *
 * Section 230 / DMCA: Platform-level protection for UGC. Contract itself only handles value escrow and access claims.
 * All legal documents and contract comments require review by licensed counsel before mainnet deployment.
 *
 * Allows filmmakers to launch NFT-backed crowdfunding campaigns.
 * Backers receive InvestmentNFTs (permanent access claim + investment proof).
 * Funds held in escrow, released only on owner-approved milestones.
 * Special 48-72h admin review window for milestone proof submissions from Producer-tier backers.
 *
 * Reuses Tier enum, patterns, and philosophy from MovieTicket + SeederCredits.
 * Arweave-first for all rich metadata/proofs (immutable, censorship-resistant).
 * Owner (platform dev) has moderation power for AI reviews + emergency controls.
 */
contract FilmmakerCampaign is ERC721A, Ownable, ReentrancyGuard {
    MovieTicket public immutable movieTicket;

    enum CampaignStatus { ACTIVE, FUNDED, FAILED, DELIVERED }

    struct TierConfig {
        uint256 price;
        uint256 maxSupply;
        uint256 sold;
    }

    struct Milestone {
        string desc;
        uint256 amount;
        bool approved;
        uint256 approvedAt;
        bool isAI;
        string proofHash;          // Arweave
        uint256 aiReviewDeadline;  // 0 if not AI
    }

    struct Campaign {
        address filmmaker;
        string metadataHash;       // Arweave JSON (pitch, title, poster, milestones, etc.)
        uint256 target;
        uint256 raised;
        uint256 deadline;
        CampaignStatus status;
        TierConfig[3] tiers;       // 0=BASIC, 1=DELUXE, 2=PRODUCER
        Milestone[] milestones;
    }

    uint256 public nextCampaignId;
    uint256 public aiReviewWindow = 72 hours;

    mapping(uint256 => Campaign) public campaigns;
    mapping(uint256 => uint256) public campaignEscrow;
    mapping(uint256 => mapping(address => uint256)) public backerTotals; // campaignId => backer => total invested

    // InvestmentNFTs (campaign-scoped for simplicity)
    mapping(uint256 => uint256) public tokenCampaign; // tokenId => campaignId
    mapping(uint256 => MovieTicket.Tier) public tokenTiers;

    // Simple mapping for campaign -> videoHash association. Enables clean hasCrowdfundAccess without relying on off-chain Arweave metadata parsing.
    // Set by filmmaker or owner (e.g. on delivery or launch). Phase 0 practicality for video gating of backers.
    mapping(uint256 => string) public campaignVideoHash;

    // === Reverse access index (O(1) crowdfund access, NO linear scan per ADR-001) ===
    // campaignId => backer => number of (non-burned) InvestmentNFTs held for that campaign.
    // Maintained on contribute (explicitly) + transfer/burn (via _afterTokenTransfers).
    mapping(uint256 => mapping(address => uint256)) public campaignBackerTokens;
    // Same index restricted to PRODUCER-tier InvestmentNFTs — powers _ownsProducerInvestment
    // (AI-proof submission gate) in O(1), no scan.
    mapping(uint256 => mapping(address => uint256)) public campaignProducerTokens;
    // keccak(videoHash) => linked campaignId + 1 (0 = unlinked). Reverse of campaignVideoHash,
    // set in setCampaignVideo, so hasCrowdfundAccess resolves a film to its campaign in O(1).
    mapping(bytes32 => uint256) private _videoCampaignPlusOne;

    event CampaignLaunched(uint256 indexed id, address filmmaker, string metadataHash, uint256 target);
    event Contribution(uint256 indexed campaignId, address indexed backer, MovieTicket.Tier tier, uint256 amount, uint256 tokenId);
    event MilestoneSubmitted(uint256 indexed campaignId, uint256 mId, string proofHash, bool isAI);
    event AIReviewed(uint256 indexed campaignId, uint256 mId, bool approved);
    event MilestoneReleased(uint256 indexed campaignId, uint256 mId, uint256 amount, address filmmaker);
    event RefundClaimed(uint256 indexed campaignId, address indexed backer, uint256 amount);
    event AIReviewWindowUpdated(uint256 newWindow);
    event CampaignVideoLinked(uint256 indexed campaignId, string videoHash);
    event CampaignFailed(uint256 indexed campaignId);

    constructor(address _movieTicket) Ownable(msg.sender) ERC721A("Decentralflix Crowdfund Pass", "DFCP") {
        require(_movieTicket != address(0), "Invalid MovieTicket");
        movieTicket = MovieTicket(_movieTicket);
    }

    function setAIReviewWindow(uint256 _hours) external onlyOwner {
        require(_hours >= 48 && _hours <= 72, "Window must be 48-72 hours");
        aiReviewWindow = _hours * 1 hours;
        emit AIReviewWindowUpdated(aiReviewWindow);
    }

    // Launch campaign (any filmmaker — anti-gatekeeping)
    function launchCampaign(
        string calldata metadataHash,
        uint256 target,
        uint256[] calldata milestoneAmounts,
        uint256[3] calldata tierPrices,
        uint256[3] calldata tierMaxSupplies,
        uint256 deadline
    ) external returns (uint256 campaignId) {
        require(bytes(metadataHash).length > 0, "Metadata required");
        require(target > 0 && milestoneAmounts.length > 0, "Invalid campaign");
        require(deadline > block.timestamp, "Deadline in past");

        campaignId = nextCampaignId++;

        Campaign storage c = campaigns[campaignId];
        c.filmmaker = msg.sender;
        c.metadataHash = metadataHash;
        c.target = target;
        c.deadline = deadline;
        c.status = CampaignStatus.ACTIVE;

        for (uint8 i = 0; i < 3; i++) {
            c.tiers[i] = TierConfig({
                price: tierPrices[i],
                maxSupply: tierMaxSupplies[i],
                sold: 0
            });
        }

        for (uint256 i = 0; i < milestoneAmounts.length; i++) {
            c.milestones.push(Milestone({
                desc: "", // Descriptions in Arweave metadata
                amount: milestoneAmounts[i],
                approved: false,
                approvedAt: 0,
                isAI: false,
                proofHash: "",
                aiReviewDeadline: 0
            }));
        }

        emit CampaignLaunched(campaignId, msg.sender, metadataHash, target);
    }

    // Backer contributes and receives InvestmentNFT (acts as access + proof)
    function contribute(uint256 campaignId, MovieTicket.Tier tier) external payable nonReentrant returns (uint256 tokenId) {
        Campaign storage c = campaigns[campaignId];
        require(c.status == CampaignStatus.ACTIVE, "Not active");
        require(block.timestamp < c.deadline, "Deadline passed");
        require(uint8(tier) < 3, "Invalid tier");

        TierConfig storage tc = c.tiers[uint8(tier)];
        require(tc.sold < tc.maxSupply, "Tier sold out");
        require(msg.value >= tc.price, "Insufficient payment");

        tokenId = _nextTokenId();
        _safeMint(msg.sender, 1);
        tokenCampaign[tokenId] = campaignId;
        tokenTiers[tokenId] = tier;
        campaignBackerTokens[campaignId][msg.sender] += 1; // index backer access (mint case)
        if (tier == MovieTicket.Tier.PRODUCER) {
            campaignProducerTokens[campaignId][msg.sender] += 1; // producer-tier gate index
        }

        tc.sold++;
        c.raised += msg.value;
        campaignEscrow[campaignId] += msg.value;
        backerTotals[campaignId][msg.sender] += msg.value;

        if (c.raised >= c.target) {
            c.status = CampaignStatus.FUNDED;
        }

        emit Contribution(campaignId, msg.sender, tier, msg.value, tokenId);
        return tokenId;
    }

    // Producer-tier backers only (check via owned InvestmentNFT + tier)
    function submitAIProof(uint256 campaignId, uint256 mId, string calldata proofHash) external {
        require(_ownsProducerInvestment(msg.sender, campaignId), "Must own Producer InvestmentNFT");
        Milestone storage m = campaigns[campaignId].milestones[mId];
        require(!m.approved && bytes(m.proofHash).length == 0, "Already submitted");

        m.isAI = true;
        m.proofHash = proofHash;
        m.aiReviewDeadline = block.timestamp + aiReviewWindow;

        emit MilestoneSubmitted(campaignId, mId, proofHash, true);
    }

    // Owner-only AI review (enforces 48-72h window)
    function reviewAISubmission(uint256 campaignId, uint256 mId, bool approved) external onlyOwner {
        Milestone storage m = campaigns[campaignId].milestones[mId];
        require(m.isAI, "Not an AI submission");
        require(block.timestamp <= m.aiReviewDeadline, "Review window closed");

        if (!approved) {
            m.proofHash = ""; // allow re-submit
            m.isAI = false;
            m.aiReviewDeadline = 0;
        }

        emit AIReviewed(campaignId, mId, approved);
    }

    // Owner approves and releases tranche from escrow
    function approveMilestoneAndRelease(uint256 campaignId, uint256 mId) external onlyOwner nonReentrant {
        Campaign storage c = campaigns[campaignId];
        Milestone storage m = c.milestones[mId];

        if (m.isAI) {
            require(block.timestamp > m.aiReviewDeadline || m.approved, "AI review pending");
        }
        require(!m.approved, "Already released");
        require(campaignEscrow[campaignId] >= m.amount, "Insufficient escrow");

        m.approved = true;
        m.approvedAt = block.timestamp;
        campaignEscrow[campaignId] -= m.amount;

        (bool sent, ) = c.filmmaker.call{value: m.amount}("");
        require(sent, "Transfer failed");

        // Check if all milestones approved
        bool allApproved = true;
        for (uint256 i = 0; i < c.milestones.length; i++) {
            if (!c.milestones[i].approved) allApproved = false;
        }
        if (allApproved) c.status = CampaignStatus.DELIVERED;

        emit MilestoneReleased(campaignId, mId, m.amount, c.filmmaker);
    }

    function claimRefund(uint256 campaignId) external nonReentrant {
        Campaign storage c = campaigns[campaignId];
        require(c.status == CampaignStatus.FAILED || (block.timestamp > c.deadline && c.raised < c.target), "Not refundable");

        uint256 amt = backerTotals[campaignId][msg.sender];
        require(amt > 0 && campaignEscrow[campaignId] >= amt, "No refund due");

        backerTotals[campaignId][msg.sender] = 0;
        campaignEscrow[campaignId] -= amt;

        (bool sent, ) = msg.sender.call{value: amt}("");
        require(sent);

        emit RefundClaimed(campaignId, msg.sender, amt);
    }

    function _ownsProducerInvestment(address user, uint256 campaignId) internal view returns (bool) {
        return campaignProducerTokens[campaignId][user] > 0;
    }

    // Phase 0: associate a campaign with the videoHash it grants crowdfund backer access to.
    // Called by the filmmaker or platform owner (e.g. once film is delivered via final milestone).
    // Enables the clean hasCrowdfundAccess check below.
    function setCampaignVideo(uint256 campaignId, string memory videoHash) external {
        Campaign storage c = campaigns[campaignId];
        require(c.filmmaker != address(0), "Campaign does not exist");
        require(msg.sender == c.filmmaker || msg.sender == owner(), "Not authorized");
        require(bytes(videoHash).length > 0, "Video hash required");

        // Clear the reverse link from any previous hash this campaign pointed at (avoids stale access).
        string memory oldHash = campaignVideoHash[campaignId];
        if (bytes(oldHash).length > 0) {
            bytes32 oldKey = _key(oldHash);
            if (_videoCampaignPlusOne[oldKey] == campaignId + 1) {
                _videoCampaignPlusOne[oldKey] = 0;
            }
        }

        campaignVideoHash[campaignId] = videoHash;
        _videoCampaignPlusOne[_key(videoHash)] = campaignId + 1;
        emit CampaignVideoLinked(campaignId, videoHash);
    }

    function _key(string memory videoHash) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(videoHash));
    }

    /**
     * @dev ERC721A transfer hook — keeps campaignBackerTokens correct on secondary transfers
     * and burns of InvestmentNFTs. Mints (from == address(0)) are handled in contribute().
     */
    function _afterTokenTransfers(
        address from,
        address to,
        uint256 startTokenId,
        uint256 quantity
    ) internal override {
        if (from == address(0)) return;
        for (uint256 i = 0; i < quantity; i++) {
            uint256 tid = startTokenId + i;
            uint256 cid = tokenCampaign[tid];
            bool isProducer = tokenTiers[tid] == MovieTicket.Tier.PRODUCER;
            if (campaignBackerTokens[cid][from] > 0) {
                campaignBackerTokens[cid][from] -= 1;
            }
            if (isProducer && campaignProducerTokens[cid][from] > 0) {
                campaignProducerTokens[cid][from] -= 1;
            }
            if (to != address(0)) {
                campaignBackerTokens[cid][to] += 1;
                if (isProducer) {
                    campaignProducerTokens[cid][to] += 1;
                }
            }
        }
    }

    /**
     * @dev Clean public view for crowdfund backer video gating.
     * Returns true if `user` owns any InvestmentNFT (DFCP) for a campaign whose
     * campaignVideoHash matches the given `videoHash`.
     * (Phase 0 uses explicit on-chain mapping set via setCampaignVideo, since
     * full campaign metadata lives on Arweave and cannot be parsed in Solidity.)
     */
    function hasCrowdfundAccess(address user, string memory videoHash) public view returns (bool) {
        if (user == address(0) || bytes(videoHash).length == 0) return false;
        uint256 cp1 = _videoCampaignPlusOne[_key(videoHash)];
        if (cp1 == 0) return false; // no campaign links this film
        return campaignBackerTokens[cp1 - 1][user] > 0;
    }

    // Admin emergency: force a campaign into FAILED so every backer can pull their refund via
    // claimRefund(). Pull pattern (no unbounded backer loop) keeps this gas-safe at any scale.
    function emergencyRefundAll(uint256 campaignId) external onlyOwner {
        Campaign storage c = campaigns[campaignId];
        require(c.filmmaker != address(0), "Campaign does not exist");
        c.status = CampaignStatus.FAILED;
        emit CampaignFailed(campaignId);
    }

    // ERC721 overrides
    function tokenURI(uint256 tokenId) public view override(ERC721A) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721A) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/mocks/MockFeeRecipients.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title MockFeeRecipients
 * @dev TEST-ONLY mocks for the F-DFLIX-1 owner-rotation receive-capability
 * guard in RevenueSplitter. A RevertingReceiver stands in for an owner
 * address that cannot receive the platform fee (which used to brick every
 * paid flow); an AcceptingReceiver is the well-behaved control.
 *
 * NOT for deployment - never referenced by scripts/deploy.ts.
 */

/// @dev Reverts on any ETH receipt: installing this as the platform owner
/// would brick buyAccess/subscribe/renew/mint flows that push the fee.
contract RevertingReceiver {
    receive() external payable {
        revert("MockFeeRecipients: cannot receive ETH");
    }
}

/// @dev Accepts ETH: the control recipient that a legitimate owner rotation
/// to a contract wallet / multisig must behave like.
contract AcceptingReceiver {
    receive() external payable {}
}

contracts/mocks/MockTicketGate.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title MockTicketGate
 * @dev TEST-ONLY mock. Stands in for the MovieTicket access/delist views that
 * Reviews.sol calls (`hasAccessToVideo` and `isFilmDelisted`). It lets tests
 * exercise the real review logic without depending on MovieTicket's on-chain
 * access check (which is a Phase-0 stub that always returns false).
 *
 * NOT for deployment — never referenced by scripts/deploy.ts.
 */
contract MockTicketGate {
    bool public globalAccess;
    mapping(address => mapping(bytes32 => bool)) public access;
    mapping(bytes32 => bool) private delisted;

    function setGlobalAccess(bool v) external {
        globalAccess = v;
    }

    function setAccess(address user, string calldata videoHash, bool v) external {
        access[user][keccak256(bytes(videoHash))] = v;
    }

    function setDelisted(string calldata videoHash, bool v) external {
        delisted[keccak256(bytes(videoHash))] = v;
    }

    function hasAccessToVideo(address user, string memory videoHash) public view returns (bool) {
        return globalAccess || access[user][keccak256(bytes(videoHash))];
    }

    function isFilmDelisted(string memory videoHash) public view returns (bool) {
        return delisted[keccak256(bytes(videoHash))];
    }
}

contracts/MovieTicket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "erc721a/contracts/ERC721A.sol";
import "./RevenueSplitter.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MovieTicket
 * @dev Decentralflix Movie Ticket NFT — Utility/Access Token Only
 *
 * IMPORTANT LEGAL POSTURE (per user-provided research + ToS integration — Step 3):
 * - This contract issues UTILITY-ONLY access tokens (Basic/Deluxe/Producer tiers).
 * - Grants on-chain verified access to films + review rights (see hasAccessToVideo).
 * - NO securities, NO investment contracts, NO expectation of profit or returns.
 * - Operator-minted: both mint functions are `onlyOwner`, so the operator
 *   submits each mint and fronts `msg.value == price` from the operator
 *   wallet; the payment is split 75/25 atomically in the same transaction
 *   (75% + rounding remainder to the `creator` argument, 25% to the owner)
 *   and nothing accrues in the contract. Direct buyer-paid purchases go
 *   through TicketNFT.mintTicket (see apps/frontend/app/mint/page.tsx).
 *
 * @notice NON-CUSTODIAL SPLITTER: every mint payment is split immediately
 * through the shared RevenueSplitter — 75% (+ rounding remainder) to the
 * creator, 25% to the platform (owner). The split is an immutable constant;
 * there is no owner-settable fee and no owner withdraw sweep. Nothing
 * accrues in the contract.
 *
 * Section 230 (Communications Decency Act) + DMCA Safe Harbor:
 * The broader Decentralflix platform relies on Section 230 immunity for third-party UGC.
 * This contract only handles access gating and payments; it does not host or moderate content.
 * DMCA: Takedowns affect access links/metadata only (immutability of chain respected).
 *
 * Producer tier + FilmmakerCampaign crowdfunding carries elevated legal risk (Howey analysis).
 * See docs/legal/RESEARCH_AND_INTEGRATION.md and ToS §4 for mandatory disclaimers.
 *
 * All users must accept the clickwrap ToS/Privacy before any mint or crowdfund action.
 *
 * All legal documents and contract comments must be reviewed by licensed counsel before mainnet.
 * This contract is provided as part of the production build for demonstration purposes.
 * NOTE: this contract is unaudited.
 *
 * Supports two types of tokens:
 *   1. Permanent Access Passes (soulbound-style or transferable)
 *   2. Burnable Single-Watch Tickets
 *
 * Higher tiers can mint additional burnable tickets that reappear in the buyer's wallet.
 */
contract MovieTicket is ERC721A, RevenueSplitter, ReentrancyGuard {
    // Business counter for videoMetadata keys (kept in sync with ERC721A token IDs via spot minting).
    // We no longer shadow ERC721A's totalSupply() or _nextTokenId().
    uint256 private _videoCounter;
    bool private _paused;

    // URI storage (ERC721A does not include ERC721URIStorage by default)
    mapping(uint256 => string) private _tokenURIs;

    enum TicketType {
        PERMANENT_PASS,
        BURNABLE_TICKET
    }

    enum Tier {
        BASIC,
        DELUXE,
        PRODUCER
    }

    struct VideoMetadata {
        string videoHash;      // Arweave or IPFS hash
        address creator;
        uint256 price;
        bool isActive;
        bool isDelisted;       // Emergency legal removal flag (set via delistFilm)
    }

    mapping(uint256 => VideoMetadata) public videoMetadata;
    mapping(uint256 => TicketType) public ticketTypes;
    mapping(uint256 => Tier) public tokenTiers;   // New: supports Basic / Deluxe / Producer
    mapping(uint256 => bool) public hasBeenWatched;

    // Producer tier perks stub (can be expanded with voting, AI collab rights, etc.)
    mapping(uint256 => bool) public hasProducerRights;

    // === Reverse access index (O(1) ownership-by-film, NO linear scan per ADR-001) ===
    // keccak(videoHash) => owner => number of (non-burned) tickets that owner currently holds for that film.
    // Maintained explicitly on mint (in the mint functions) and on transfer/burn (via _afterTokenTransfers).
    // Powers hasAccessToVideo() in O(1) — replaces the old totalSupply scan / always-false stub.
    mapping(bytes32 => mapping(address => uint256)) private _filmAccessCount;

    // Per-address tier holdings: count of [BASIC, DELUXE, PRODUCER] tickets currently held.
    // Maintained alongside _filmAccessCount; powers highestTierMultiplier() (used by SeederCredits
    // to apply tier earning bonuses) in O(1), no scan.
    mapping(address => uint256[3]) private _tierBalance;

    // === Emergency Legal Removal (T16 — CSAM / illegal content only) ===
    mapping(bytes32 => bool) public isDelisted;
    mapping(bytes32 => string) public delistReason;
    mapping(bytes32 => uint256) public delistedAt;

    // ── Errors ────────────────────────────────────────────────────────────
    error IncorrectPayment(uint256 expected, uint256 received);

    event VideoMinted(
        uint256 indexed tokenId,
        address indexed creator,
        address indexed to,
        string videoHash,
        TicketType ticketType,
        Tier tier,
        uint256 price,
        uint256 platformFee,
        uint256 creatorShare
    );
    event CreatorPaid(uint256 indexed tokenId, address indexed creator, uint256 amount);
    event TicketBurned(uint256 indexed tokenId, address indexed viewer);
    event Paused(address account);
    event Unpaused(address account);
    event TierUpgraded(uint256 indexed tokenId, Tier newTier); // Future: allow upgrading tiers

    // Emergency legal removal events (only for illegal content — political deplatforming is not removable)
    event ContentDelisted(string indexed videoHash, string reason, uint256 timestamp, address by);
    event ContentRestored(string indexed videoHash, uint256 timestamp, address by);

    constructor() ERC721A("Decentralflix Movie Ticket", "DFMT") Ownable(msg.sender) {}

    /**
     * @dev ERC721A hook — start token IDs at 0 to match prior ERC721 behavior.
     */
    function _startTokenId() internal pure override returns (uint256) {
        return 0;
    }

    /**
     * @dev Internal helper to set token URI (replaces ERC721URIStorage behavior).
     */
    function _setTokenURI(uint256 tokenId, string memory uri) internal {
        _tokenURIs[tokenId] = uri;
    }

    /**
     * @dev Canonical film key. Matches the hashing used by the delisting maps so
     * access and delisting share the exact same key space.
     */
    function _filmKey(string memory videoHash) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(videoHash));
    }

    /**
     * @dev ERC721A transfer hook — keeps _filmAccessCount correct on secondary transfers
     * and burns. Mints (from == address(0)) are accounted for explicitly in the mint
     * functions, so they are skipped here to avoid double counting.
     */
    function _afterTokenTransfers(
        address from,
        address to,
        uint256 startTokenId,
        uint256 quantity
    ) internal override {
        if (from == address(0)) return; // mint: handled in mint functions
        for (uint256 i = 0; i < quantity; i++) {
            uint256 tokenId = startTokenId + i;
            bytes32 key = _filmKey(videoMetadata[tokenId].videoHash);
            uint256 tierIdx = uint256(uint8(tokenTiers[tokenId]));
            if (_filmAccessCount[key][from] > 0) {
                _filmAccessCount[key][from] -= 1;
            }
            if (_tierBalance[from][tierIdx] > 0) {
                _tierBalance[from][tierIdx] -= 1;
            }
            if (to != address(0)) {
                _filmAccessCount[key][to] += 1; // transfer recipient gains access
                _tierBalance[to][tierIdx] += 1;
            }
            // to == address(0) is a burn: access + tier holding simply removed from `from`.
        }
    }

    modifier whenNotPaused() {
        require(!_paused, "MovieTicket: paused");
        _;
    }

    function pause() public onlyOwner {
        _paused = true;
        emit Paused(msg.sender);
    }

    function unpause() public onlyOwner {
        _paused = false;
        emit Unpaused(msg.sender);
    }

    // === Emergency Legal Removal (T16) — ONLY for illegal content (CSAM, etc.) ===
    // Censorship resistance applies to political pressure on *legal* content.
    function delistFilm(string calldata videoHash, string calldata reason) external onlyOwner {
        bytes32 hashKey = keccak256(abi.encodePacked(videoHash));
        isDelisted[hashKey] = true;
        delistReason[hashKey] = reason;
        delistedAt[hashKey] = block.timestamp;
        emit ContentDelisted(videoHash, reason, block.timestamp, msg.sender);
    }

    function restoreFilm(string calldata videoHash) external onlyOwner {
        bytes32 hashKey = keccak256(abi.encodePacked(videoHash));
        isDelisted[hashKey] = false;
        emit ContentRestored(videoHash, block.timestamp, msg.sender);
    }

    function isFilmDelisted(string memory videoHash) public view returns (bool) {
        return isDelisted[keccak256(abi.encodePacked(videoHash))];
    }

    /**
     * @dev Split the mint payment 75/25 through the shared RevenueSplitter.
     * Payment must equal the price exactly — with no owner withdraw sweep,
     * any excess would be locked in the contract forever. Reverts on a zero
     * creator; the creator's share is NEVER redirected.
     */
    function _splitMintPayment(address creator, uint256 price)
        internal
        returns (uint256 creatorShare, uint256 platformFee)
    {
        if (msg.value != price) revert IncorrectPayment(price, msg.value);
        if (msg.value == 0) return (0, 0); // free mint: no transfers, nothing accrues
        return _splitRevenue(creator);
    }

    function mintPermanentPass(
        address to,
        address creator,
        string memory videoHash,
        uint256 price,
        Tier tier // New parameter for multi-tier support
    ) public payable onlyOwner whenNotPaused nonReentrant returns (uint256) {
        require(uint8(tier) <= uint8(Tier.PRODUCER), "Invalid tier");

        (uint256 creatorShare, uint256 platformFee) = _splitMintPayment(creator, price);

        uint256 tokenId = _videoCounter++;

        // Pay creator immediately at the immutable 75/25 split (protects them
        // from future gas price increases). The platform fee goes straight to
        // the owner — nothing accrues in the contract, so there is nothing for
        // an owner sweep to take.
        if (creatorShare > 0) {
            emit CreatorPaid(tokenId, creator, creatorShare);
        }

        // Sequential ERC721A mint of exactly one token. Because every mint here is a single
        // token and _startTokenId() == 0, the minted id equals our _videoCounter value above,
        // so metadata/event keys stay in sync. (_safeMintSpot is NOT usable without overriding
        // _sequentialUpTo(); using it here reverted every mint with SpotMintTokenIdTooSmall.)
        _safeMint(to, 1);
        _setTokenURI(tokenId, videoHash);

        videoMetadata[tokenId] = VideoMetadata({
            videoHash: videoHash,
            creator: creator,
            price: price,
            isActive: true,
            isDelisted: false
        });

        ticketTypes[tokenId] = TicketType.PERMANENT_PASS;
        tokenTiers[tokenId] = tier;
        _filmAccessCount[_filmKey(videoHash)][to] += 1; // index ownership for O(1) access checks
        _tierBalance[to][uint256(uint8(tier))] += 1; // index tier holdings for O(1) tier multiplier

        if (tier == Tier.PRODUCER) {
            hasProducerRights[tokenId] = true;
        }

        emit VideoMinted(
            tokenId,
            creator,
            to,
            videoHash,
            TicketType.PERMANENT_PASS,
            tier,
            price,
            platformFee,
            creatorShare
        );
        return tokenId;
    }

    function mintBurnableTicket(
        address to,
        address creator,
        string memory videoHash,
        uint256 price,
        Tier tier // New parameter for multi-tier support
    ) public payable onlyOwner whenNotPaused nonReentrant returns (uint256) {
        require(uint8(tier) <= uint8(Tier.PRODUCER), "Invalid tier");

        (uint256 creatorShare, uint256 platformFee) = _splitMintPayment(creator, price);

        uint256 tokenId = _videoCounter++;

        // Pay creator immediately at the immutable 75/25 split. The platform
        // fee goes straight to the owner — nothing accrues in the contract.
        if (creatorShare > 0) {
            emit CreatorPaid(tokenId, creator, creatorShare);
        }

        // Sequential ERC721A mint of exactly one token. Because every mint here is a single
        // token and _startTokenId() == 0, the minted id equals our _videoCounter value above,
        // so metadata/event keys stay in sync. (_safeMintSpot is NOT usable without overriding
        // _sequentialUpTo(); using it here reverted every mint with SpotMintTokenIdTooSmall.)
        _safeMint(to, 1);
        _setTokenURI(tokenId, videoHash);

        videoMetadata[tokenId] = VideoMetadata({
            videoHash: videoHash,
            creator: creator,
            price: price,
            isActive: true,
            isDelisted: false
        });

        ticketTypes[tokenId] = TicketType.BURNABLE_TICKET;
        tokenTiers[tokenId] = tier;
        _filmAccessCount[_filmKey(videoHash)][to] += 1; // index ownership for O(1) access checks
        _tierBalance[to][uint256(uint8(tier))] += 1; // index tier holdings for O(1) tier multiplier

        if (tier == Tier.PRODUCER) {
            hasProducerRights[tokenId] = true;
        }

        emit VideoMinted(
            tokenId,
            creator,
            to,
            videoHash,
            TicketType.BURNABLE_TICKET,
            tier,
            price,
            platformFee,
            creatorShare
        );
        return tokenId;
    }

    // Burn a single-watch ticket after viewing (or on first play)
    function burnTicket(uint256 tokenId) public {
        require(ownerOf(tokenId) == msg.sender, "Not ticket owner");
        require(ticketTypes[tokenId] == TicketType.BURNABLE_TICKET, "Not a burnable ticket");
        require(!hasBeenWatched[tokenId], "Ticket already used");

        hasBeenWatched[tokenId] = true;
        _burn(tokenId);

        emit TicketBurned(tokenId, msg.sender);
    }

    // Back-compat alias for the access check. Previously an always-true MVP placeholder
    // (a latent always-grant footgun); now delegates to the real O(1) hasAccessToVideo so it
    // can never wrongly grant access if any caller wires it up.
    function hasAccess(address viewer, string memory videoHash) public view returns (bool) {
        return hasAccessToVideo(viewer, videoHash);
    }

    /**
     * @dev Number of tokens EVER minted (token IDs are dense from 0, so this is
     * maxTokenId + 1). Unlike ERC721A's totalSupply() it does NOT shrink on
     * burn. Off-chain enumerators (e.g. useOwnedFilms) must loop to this, NOT to
     * totalSupply() — otherwise tokens minted after any burn are skipped and
     * vanish from the UI. on-chain access itself is mapping-based
     * (_filmAccessCount) and was never affected.
     */
    function totalMinted() public view returns (uint256) {
        return _videoCounter;
    }

    // === Fee Calculation Helpers (for frontend / off-chain use) ===
    // Wired to the shared immutable split — the owner cannot change these.

    function getPlatformFee(uint256 price) public pure returns (uint256) {
        return (price * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
    }

    function getCreatorShare(uint256 price) public pure returns (uint256) {
        return price - getPlatformFee(price);
    }

    /**
     * @dev O(1) on-chain access check. Returns true iff `user` currently holds at least one
     * (non-burned) ticket whose videoHash matches, and the film is not delisted.
     *
     * Backed by the _filmAccessCount reverse index maintained on mint/transfer/burn — there is
     * NO totalSupply iteration, so this scales for mass-mint launches (ADR-001 compliant).
     * Off-chain indexers may still be used for richer queries, but ownership/access gating
     * (e.g. Reviews) can now rely on this view directly.
     */
    function hasAccessToVideo(address user, string memory videoHash) public view returns (bool) {
        if (isFilmDelisted(videoHash)) return false; // T16: illegal content is immediately inaccessible
        return _filmAccessCount[_filmKey(videoHash)][user] > 0;
    }

    /**
     * @dev Number of (non-burned) tickets `user` holds for `videoHash`. Exposed for off-chain
     * tooling / debugging. Does not consider delisting (use hasAccessToVideo for gating).
     */
    function accessBalanceOf(address user, string memory videoHash) public view returns (uint256) {
        return _filmAccessCount[_filmKey(videoHash)][user];
    }

    /**
     * @dev Count of [BASIC, DELUXE, PRODUCER] tickets currently held by `user`. O(1), no scan.
     */
    function tierBalanceOf(address user)
        public
        view
        returns (uint256 basic, uint256 deluxe, uint256 producer)
    {
        return (_tierBalance[user][0], _tierBalance[user][1], _tierBalance[user][2]);
    }

    /**
     * @dev Earning multiplier (basis of 100 = 1.0x) based on the user's highest owned tier:
     * PRODUCER = 150 (1.5x), DELUXE = 125 (1.25x), otherwise 100 (1.0x). Used by SeederCredits.
     */
    function highestTierMultiplier(address user) public view returns (uint256) {
        if (_tierBalance[user][uint256(uint8(Tier.PRODUCER))] > 0) return 150;
        if (_tierBalance[user][uint256(uint8(Tier.DELUXE))] > 0) return 125;
        return 100;
    }

    // The following functions are overrides required by Solidity.
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721A)
        returns (string memory)
    {
        string memory uri = _tokenURIs[tokenId];
        if (bytes(uri).length == 0) {
            return super.tokenURI(tokenId); // fallback to ERC721A default (empty or base)
        }
        return uri;
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721A)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/PayPerView.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RevenueSplitter.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title PayPerView
 * @author Decentralflix — Phase 2
 * @notice One-time film purchases. The platform owner registers films, naming
 * the filmmaker explicitly (the filmId namespace is payment-bearing, so open
 * registration would let a front-runner claim any filmId and irreversibly
 * capture its revenue share); filmmakers set their own prices via
 * setFilmPrice. Buyers pay the EXACT price (under- or overpayment reverts —
 * there are no refunds and no partial credit) and receive permanent access.
 * @notice NON-CUSTODIAL SPLITTER: every purchase is split immediately through
 * the shared RevenueSplitter — 75% to the filmmaker, 25% to the platform
 * (owner). The split is an immutable constant; the owner cannot change it and
 * there is no owner-settable fee. No revenue accrues in the contract.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 * NOTE: this contract is unaudited.
 */
contract PayPerView is RevenueSplitter, ReentrancyGuard {
    /// @notice A purchasable film.
    struct Film {
        address filmmaker; // named explicitly by the owner at registration; receives the 75% share
        uint256 priceWei; // exact purchase price in wei (0 = free film)
        bool exists; // registration guard
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error InvalidFilmId();
    error ZeroAddress();
    error FilmAlreadyRegistered(uint256 filmId);
    error FilmNotFound(uint256 filmId);
    error NotFilmmaker(uint256 filmId, address caller);
    error IncorrectPayment(uint256 expected, uint256 received);

    // ── Events ────────────────────────────────────────────────────────────
    event FilmRegistered(uint256 indexed filmId, address indexed filmmaker, uint256 priceWei);
    event FilmPriceUpdated(uint256 indexed filmId, uint256 oldPrice, uint256 newPrice);
    event AccessPurchased(
        uint256 indexed filmId,
        address indexed buyer,
        uint256 pricePaid,
        address indexed filmmaker,
        uint256 filmmakerShare,
        uint256 platformFee
    );

    mapping(uint256 => Film) private _films; // filmId => Film
    mapping(uint256 => mapping(address => bool)) private _access; // filmId => buyer => permanent access

    constructor() Ownable(msg.sender) {}

    // ── Film registry (owner only) ────────────────────────────────────────

    /**
     * @notice Register a film for pay-per-view sale. Only the platform owner
     * may register: an open filmId namespace would let a front-runner claim
     * any filmId and irreversibly capture its 75% filmmaker revenue share
     * (F-3). The owner names the filmmaker explicitly; the filmmaker is the
     * only address that can update the price afterward, and the filmmaker
     * address can never be changed.
     * @param filmId Platform-unique film identifier (must be non-zero and unused).
     * @param priceWei Exact purchase price in wei (0 allowed for free films).
     * @param filmmaker Address receiving the 75% (+ rounding remainder) share (non-zero).
     */
    function registerFilm(uint256 filmId, uint256 priceWei, address filmmaker) external onlyOwner {
        if (filmId == 0) revert InvalidFilmId();
        if (_films[filmId].exists) revert FilmAlreadyRegistered(filmId);
        if (filmmaker == address(0)) revert ZeroAddress();

        _films[filmId] = Film({filmmaker: filmmaker, priceWei: priceWei, exists: true});

        emit FilmRegistered(filmId, filmmaker, priceWei);
    }

    /// @notice Update the purchase price. Only the film's filmmaker may call.
    function setFilmPrice(uint256 filmId, uint256 newPrice) external {
        Film storage film = _getFilmOrRevert(filmId);
        if (film.filmmaker != msg.sender) revert NotFilmmaker(filmId, msg.sender);

        uint256 oldPrice = film.priceWei;
        film.priceWei = newPrice;

        emit FilmPriceUpdated(filmId, oldPrice, newPrice);
    }

    // ── Purchase ──────────────────────────────────────────────────────────

    /**
     * @notice Buy permanent access to a film. Payment must equal the film's
     * current price EXACTLY — overpayment is not refunded, it reverts.
     * The payment is split immediately: 75% (+ rounding remainder) to the
     * filmmaker, 25% to the platform. Nothing accrues in the contract.
     */
    function buyAccess(uint256 filmId) external payable nonReentrant {
        Film memory film = _getFilmOrRevert(filmId);
        if (msg.value != film.priceWei) revert IncorrectPayment(film.priceWei, msg.value);

        _access[filmId][msg.sender] = true;

        (uint256 filmmakerShare, uint256 platformFee) = _splitRevenue(film.filmmaker);

        emit AccessPurchased(
            filmId,
            msg.sender,
            msg.value,
            film.filmmaker,
            filmmakerShare,
            platformFee
        );
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice True if `user` has purchased permanent access to `filmId`.
    function hasAccess(address user, uint256 filmId) external view returns (bool) {
        return _access[filmId][user];
    }

    /// @notice Full metadata for a registered film. Reverts if unregistered.
    function getFilm(uint256 filmId) external view returns (Film memory) {
        return _getFilmOrRevert(filmId);
    }

    function _getFilmOrRevert(uint256 filmId) internal view returns (Film storage) {
        Film storage film = _films[filmId];
        if (!film.exists) revert FilmNotFound(filmId);
        return film;
    }
}

contracts/ProofRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ProofRegistry
 * @author Decentralflix — Phase 2 (step 5)
 * @notice On-chain registry of film fragment manifests, anchored as Merkle roots.
 *
 * A filmmaker (or the contract owner) registers a film's fragment manifest by
 * publishing the Merkle root over the per-fragment sha256 leaf hashes produced
 * by the Decentralflix storage JS package (`splitBuffer` → `sha256Hex` per fragment →
 * `buildMerkleRoot`). Anyone can then call {verifyFragment} to check that a
 * given fragment belongs to the registered manifest — the tamper-evidence
 * primitive that lets a client reject a corrupted or substituted fragment
 * before decryption.
 *
 * TREE CONVENTION (must match `packages/storage/src/merkle.js` exactly):
 * - Leaves are the 32 raw bytes of each fragment's sha256 hex digest.
 * - Internal node = sha256(left || right), order-preserving (NOT sorted).
 * - Odd layers duplicate the last node before pairing.
 * - A single-fragment film has root == its leaf hash and an empty proof.
 *
 * @dev NOTE ON OpenZeppelin MerkleProof: OZ's `MerkleProof.verify` hardcodes
 * keccak256 for internal node hashing, which is INCOMPATIBLE with this
 * registry's sha256-based tree (the storage layer standardizes on sha256
 * end-to-end, fragment hashes included). This contract therefore implements
 * its own sha256 verifier ({_processProof}) that mirrors `merkle.js` byte for
 * byte. The round trip is proven by the end-to-end test in
 * `test/ProofRegistry.test.ts` (storage → root → register → verify).
 *
 * REGISTRATION TRUST MODEL: the first caller to register a `filmId` becomes
 * its `registrant`; afterwards only the registrant or the contract owner may
 * update the manifest. There is no on-chain filmmaker identity check here —
 * front-running a `filmId` registration is possible, so integrators should
 * register manifests promptly and treat `getManifest`'s `registrant` field as
 * the authority signal.
 */
contract ProofRegistry is Ownable {
    /// @notice A registered film manifest.
    struct Manifest {
        bytes32 merkleRoot; // root over the fragment sha256 leaves
        uint256 fragmentCount; // number of leaves the root commits to
        string manifestArweaveTx; // Arweave tx id of the full JSON manifest (may be empty)
        address registrant; // address that first registered this filmId
        uint64 registeredAt; // block.timestamp of first registration
        uint64 updatedAt; // block.timestamp of last update
        bool exists; // registration guard
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error InvalidFilmId();
    error InvalidRoot();
    error InvalidFragmentCount();
    error ManifestNotFound(uint256 filmId);
    error NotRegistrantOrOwner(uint256 filmId, address caller);
    error FragmentIndexOutOfBounds(uint256 filmId, uint256 index, uint256 fragmentCount);
    error ProofLengthMismatch(uint256 expected, uint256 actual);

    // ── Events ────────────────────────────────────────────────────────────
    event ManifestRegistered(
        uint256 indexed filmId,
        address indexed registrant,
        bytes32 merkleRoot,
        uint256 fragmentCount,
        string manifestArweaveTx
    );
    event ManifestUpdated(
        uint256 indexed filmId,
        address indexed updater,
        bytes32 oldRoot,
        bytes32 newRoot,
        uint256 fragmentCount,
        string manifestArweaveTx
    );

    mapping(uint256 => Manifest) private _manifests; // filmId => Manifest

    constructor() Ownable(msg.sender) {}

    // ── Registration ──────────────────────────────────────────────────────

    /**
     * @notice Register (first call) or update (registrant/owner only) a film's
     * fragment manifest.
     * @param filmId Platform-unique film identifier (must be non-zero).
     * @param merkleRoot Root of the sha256 Merkle tree over the fragment
     * hashes, as produced by `buildMerkleRoot` in the storage package.
     * @param fragmentCount Number of fragments (leaves) the root commits to.
     * @param manifestArweaveTx Arweave tx id of the full JSON manifest
     * (informational; may be empty if not yet posted).
     */
    function registerManifest(
        uint256 filmId,
        bytes32 merkleRoot,
        uint256 fragmentCount,
        string calldata manifestArweaveTx
    ) external {
        if (filmId == 0) revert InvalidFilmId();
        if (merkleRoot == bytes32(0)) revert InvalidRoot();
        if (fragmentCount == 0) revert InvalidFragmentCount();

        Manifest storage m = _manifests[filmId];
        if (!m.exists) {
            m.merkleRoot = merkleRoot;
            m.fragmentCount = fragmentCount;
            m.manifestArweaveTx = manifestArweaveTx;
            m.registrant = msg.sender;
            m.registeredAt = uint64(block.timestamp);
            m.updatedAt = uint64(block.timestamp);
            m.exists = true;
            emit ManifestRegistered(filmId, msg.sender, merkleRoot, fragmentCount, manifestArweaveTx);
        } else {
            if (msg.sender != m.registrant && msg.sender != owner()) {
                revert NotRegistrantOrOwner(filmId, msg.sender);
            }
            bytes32 oldRoot = m.merkleRoot;
            m.merkleRoot = merkleRoot;
            m.fragmentCount = fragmentCount;
            m.manifestArweaveTx = manifestArweaveTx;
            m.updatedAt = uint64(block.timestamp);
            emit ManifestUpdated(
                filmId,
                msg.sender,
                oldRoot,
                merkleRoot,
                fragmentCount,
                manifestArweaveTx
            );
        }
    }

    /**
     * @notice Return the registered manifest for a film.
     * @param filmId Platform-unique film identifier.
     */
    function getManifest(uint256 filmId)
        external
        view
        returns (
            bytes32 merkleRoot,
            uint256 fragmentCount,
            string memory manifestArweaveTx,
            address registrant,
            uint64 registeredAt,
            uint64 updatedAt
        )
    {
        Manifest storage m = _manifests[filmId];
        if (!m.exists) revert ManifestNotFound(filmId);
        return (
            m.merkleRoot,
            m.fragmentCount,
            m.manifestArweaveTx,
            m.registrant,
            m.registeredAt,
            m.updatedAt
        );
    }

    // ── Verification ──────────────────────────────────────────────────────

    /**
     * @notice Check that a fragment belongs to a registered manifest.
     * @param filmId Platform-unique film identifier.
     * @param fragmentIndex Index of the fragment (0-based leaf position).
     * @param leafHash sha256 digest of the fragment's stored (encrypted,
     * wire-format) bytes, as 32 raw bytes.
     * @param proof Sibling hashes from leaf to root, as produced by
     * `getProof` in the storage package (`packages/storage/src/merkle.js`). Length must equal the tree
     * depth (0 for a single-fragment film).
     * @return True iff the proof recomputes to the registered root.
     */
    function verifyFragment(
        uint256 filmId,
        uint256 fragmentIndex,
        bytes32 leafHash,
        bytes32[] calldata proof
    ) external view returns (bool) {
        Manifest storage m = _manifests[filmId];
        if (!m.exists) revert ManifestNotFound(filmId);
        if (fragmentIndex >= m.fragmentCount) {
            revert FragmentIndexOutOfBounds(filmId, fragmentIndex, m.fragmentCount);
        }
        uint256 expected = _treeDepth(m.fragmentCount);
        if (proof.length != expected) revert ProofLengthMismatch(expected, proof.length);
        return _processProof(fragmentIndex, leafHash, proof) == m.merkleRoot;
    }

    /**
     * @dev Tree depth = number of proof elements for `leafCount` leaves:
     * 0 for a single leaf, otherwise ceil(log2(leafCount)).
     */
    function _treeDepth(uint256 leafCount) internal pure returns (uint256) {
        uint256 depth = 0;
        uint256 size = leafCount;
        while (size > 1) {
            size = (size + 1) / 2;
            depth++;
        }
        return depth;
    }

    /**
     * @dev Recompute the root from a leaf and its sibling path using the
     * storage layer's convention: sha256(left || right), order-preserving.
     * Odd layers are duplicated by the prover (the duplicate is supplied as
     * the sibling), so no special-casing is needed here.
     */
    function _processProof(
        uint256 index,
        bytes32 leafHash,
        bytes32[] calldata proof
    ) internal pure returns (bytes32) {
        bytes32 computed = leafHash;
        uint256 idx = index;
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 sibling = proof[i];
            if (idx % 2 == 0) {
                computed = sha256(abi.encodePacked(computed, sibling));
            } else {
                computed = sha256(abi.encodePacked(sibling, computed));
            }
            idx /= 2;
        }
        return computed;
    }
}

contracts/RevenueSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title RevenueSplitter
 * @author Decentralflix — Phase 2
 * @notice Single source of truth for the Decentralflix creator/platform split.
 * EVERY contract that takes money from a viewer splits through here, so the
 * whitepaper's "75% to the creator, 25% to the platform" claim cannot drift
 * apart between contracts again (owner decision 2026-09-29: one rule,
 * everywhere, so the copy is true).
 *
 * Rules, encoded once:
 *  - The split is an immutable constant (PLATFORM_FEE_BPS = 2500). There is
 *    no setter by design; the owner cannot change it.
 *  - The platform fee is computed with floor division on msg.value; the
 *    creator receives `msg.value - fee`, so the rounding remainder ALWAYS
 *    favors the creator.
 *  - A zero creator address reverts (MissingCreator). There is NO owner
 *    fallback — the creator's share is never redirected.
 *  - The creator address is set by each inheriting contract at registration /
 *    creation time and can never be changed afterward.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 * NOTE: this contract is unaudited.
 */
abstract contract RevenueSplitter is Ownable {
    /// @notice Platform fee in basis points — IMMUTABLE. 2500 bps = 25%.
    /// The creator always receives 75% plus the rounding remainder.
    /// Defined once, here; there is no setter by design.
    uint256 public constant PLATFORM_FEE_BPS = 2500;

    /// @notice Basis-points denominator (10000 = 100%).
    uint256 public constant BPS_DENOMINATOR = 10000;

    // ── Errors ────────────────────────────────────────────────────────────
    error MissingCreator();
    error TransferFailed();

    // ── Events ────────────────────────────────────────────────────────────
    event RevenueSplit(address indexed creator, uint256 creatorShare, uint256 platformFee);

    /**
     * @notice Split msg.value 75/25 between `creator` and the platform (owner).
     * The platform fee is computed with floor division; the creator receives
     * `msg.value - fee`, so the rounding remainder always favors the creator.
     * Reverts on a zero creator — the creator's share is NEVER redirected to
     * the owner, and the owner cannot change the split.
     * @param creator Address receiving the 75% (+ rounding remainder) share.
     * @return creatorShare wei sent to the creator.
     * @return platformFee wei sent to the platform (owner).
     */
    function _splitRevenue(address creator)
        internal
        returns (uint256 creatorShare, uint256 platformFee)
    {
        if (creator == address(0)) revert MissingCreator();

        platformFee = (msg.value * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        creatorShare = msg.value - platformFee;

        (bool okFee, ) = owner().call{value: platformFee}("");
        if (!okFee) revert TransferFailed();
        (bool okCreator, ) = creator.call{value: creatorShare}("");
        if (!okCreator) revert TransferFailed();

        emit RevenueSplit(creator, creatorShare, platformFee);
    }
}

