// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./MovieTicket.sol";
import "./FilmmakerCampaign.sol";

/**
 * @title Reviews
 * @dev Decentralized, NFT-gated ratings and comments system — CORE PRODUCT FEATURE.
 *
 * Only verified owners (MovieTicket OR FilmmakerCampaign InvestmentNFT via hasCrowdfundAccess)
 * can submit/edit a single review per film. This enforces "your voice is verified because you own it on-chain".
 *
 * LEGAL TIE-IN (Step 3):
 * - Gating relies on the utility NFTs defined in MovieTicket + FilmmakerCampaign.
 * - Section 230 protects the platform for hosting these third-party reviews.
 * - DMCA: Reviews containing infringing material can be delisted via platform action (no on-chain deletion).
 * - All review eligibility is strictly on-chain (no off-chain KYC or custody).
 *
 * See ToS §3 (UGC + Zero-Censorship) and RESEARCH_AND_INTEGRATION.md.
 * All legal text and contract comments require review by licensed counsel before mainnet deployment.
 *
 * Only verified owners can review: holders of a MovieTicket OR crowdfund InvestmentNFT
 * (via FilmmakerCampaign.hasCrowdfundAccess after filmmaker calls setCampaignVideo).
 * This is the core social layer for the platform — verified owner voice only.
 */
contract Reviews {
    struct Review {
        address reviewer;
        uint8 rating;      // 1-5
        string comment;
        uint256 timestamp;
    }

    // videoHash => reviewer => Review  (enforces one review per user per film)
    mapping(string => mapping(address => Review)) private reviews;

    // videoHash => list of reviewers (for enumeration in Phase 0)
    mapping(string => address[]) public reviewersByVideo;

    MovieTicket public immutable movieTicket;
    FilmmakerCampaign public immutable filmmakerCampaign;

    event ReviewSubmitted(
        string indexed videoHash,
        address indexed reviewer,
        uint8 rating,
        string comment,
        uint256 timestamp
    );

    event ReviewUpdated(
        string indexed videoHash,
        address indexed reviewer,
        uint8 rating,
        string comment,
        uint256 timestamp
    );

    constructor(address _movieTicket, address _filmmakerCampaign) {
        movieTicket = MovieTicket(_movieTicket);
        filmmakerCampaign = FilmmakerCampaign(_filmmakerCampaign);
    }

    modifier onlyVerifiedOwner(string memory videoHash) {
        // T16: delisted (illegal) content is immediately non-reviewable
        require(!movieTicket.isFilmDelisted(videoHash), "Film has been delisted for legal reasons");
        bool hasTicket = movieTicket.hasAccessToVideo(msg.sender, videoHash);
        bool hasCrowdfund = address(filmmakerCampaign) != address(0) &&
            filmmakerCampaign.hasCrowdfundAccess(msg.sender, videoHash);
        require(
            hasTicket || hasCrowdfund,
            "Must own a MovieTicket or crowdfund InvestmentNFT for this video to review"
        );
        _;
    }

    function submitReview(
        string memory videoHash,
        uint8 rating,
        string memory comment
    ) external onlyVerifiedOwner(videoHash) {
        require(rating >= 1 && rating <= 5, "Rating must be 1-5");
        require(bytes(comment).length > 0 && bytes(comment).length <= 500, "Comment too long");

        bool isNew = reviews[videoHash][msg.sender].reviewer == address(0);

        if (isNew) {
            reviewersByVideo[videoHash].push(msg.sender);
        }

        reviews[videoHash][msg.sender] = Review({
            reviewer: msg.sender,
            rating: rating,
            comment: comment,
            timestamp: block.timestamp
        });

        if (isNew) {
            emit ReviewSubmitted(videoHash, msg.sender, rating, comment, block.timestamp);
        } else {
            emit ReviewUpdated(videoHash, msg.sender, rating, comment, block.timestamp);
        }
    }

    function getReview(string memory videoHash, address reviewer) external view returns (Review memory) {
        if (movieTicket.isFilmDelisted(videoHash)) {
            return Review({reviewer: address(0), rating: 0, comment: "", timestamp: 0});
        }
        return reviews[videoHash][reviewer];
    }

    function getReviews(string memory videoHash) external view returns (Review[] memory) {
        if (movieTicket.isFilmDelisted(videoHash)) {
            return new Review[](0);
        }
        address[] memory reviewers = reviewersByVideo[videoHash];
        Review[] memory result = new Review[](reviewers.length);

        for (uint256 i = 0; i < reviewers.length; i++) {
            result[i] = reviews[videoHash][reviewers[i]];
        }
        return result;
    }

    function getReviewCount(string memory videoHash) external view returns (uint256) {
        if (movieTicket.isFilmDelisted(videoHash)) {
            return 0;
        }
        return reviewersByVideo[videoHash].length;
    }

    function hasReviewed(string memory videoHash, address reviewer) external view returns (bool) {
        if (movieTicket.isFilmDelisted(videoHash)) {
            return false;
        }
        return reviews[videoHash][reviewer].reviewer != address(0);
    }
}

contracts/SeederCredits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./MovieTicket.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SeederCredits
 * @dev Decentralflix P2P Hosting Credit System (Phase 0/1 hybrid MVP)
 *
 * Users earn redeemable credits by seeding/hosting film content.
 * Credits formula: uptime + bandwidth + peers (reported off-chain via Arweave, claimed on-chain).
 *
 * Hybrid design (per full vision):
 * - Heavy reports anchored on Arweave (immutable, censorship-resistant).
 * - On-chain lightweight ledger for balances + redemptions.
 * - Temporary platform attestor (owner-controlled EOA) for claim validation (bootstrap; replaceable later with multi-sig/indexers).
 *
 * Ties directly into NFT tiers: Higher tiers (Deluxe/Producer) get multipliers on earnings and redemptions.
 * Redeemable for perks (fee discounts, free tickets, future Producer eligibility).
 */
contract SeederCredits is Ownable, ReentrancyGuard {
    MovieTicket public immutable movieTicket;

    // Platform attestor (temporary trusted oracle for Phase 0/1; can be multi-sig later)
    address public platformAttestor;

    mapping(address => uint256) public credits;
    mapping(address => uint256) public lastClaimTimestamp;
    // Consume-once registry: each attestor-signed report hash can be claimed exactly once.
    // Replay protection (W3B-001): a signed report cannot be resubmitted after the
    // cooldown window, so one attestor signature can never mint credits twice.
    mapping(bytes32 => bool) public consumedReports;

    // Emergency switch: when true, new seeding-credit claims are blocked (owner-controlled).
    bool public claimsPaused;

    uint256 public constant MIN_CLAIM_COOLDOWN = 1 days;
    uint256 public constant MAX_REPORT_AGE = 7 days;

    // Events for transparency and indexing
    event CreditsEarned(
        address indexed seeder,
        uint256 amount,
        string arweaveTxId,
        uint256 tierMultiplier
    );
    event CreditsRedeemed(
        address indexed seeder,
        uint256 amount,
        bytes32 indexed rewardType
    );
    event PlatformAttestorUpdated(address oldAttestor, address newAttestor);

    constructor(address _movieTicket) Ownable(msg.sender) {
        require(_movieTicket != address(0), "Invalid MovieTicket");
        movieTicket = MovieTicket(_movieTicket);
        platformAttestor = msg.sender; // Owner starts as attestor
    }

    function setPlatformAttestor(address _newAttestor) external onlyOwner {
        require(_newAttestor != address(0), "Invalid attestor");
        address old = platformAttestor;
        platformAttestor = _newAttestor;
        emit PlatformAttestorUpdated(old, _newAttestor);
    }

    /**
     * @dev Claim credits from a signed Arweave report.
     * Report must be recent (signed within MAX_REPORT_AGE), signed by platformAttestor,
     * and seeder must hold at least one ticket for referenced content.
     * Each signed report is consume-once: the attestor signs a fresh nonce per report,
     * and the message hash can never be claimed twice (W3B-001).
     * Credits = (uptime + bandwidth + peers) * tierMultiplier (from highest owned tier).
     */
    function submitSeedingReport(
        string calldata arweaveTxId,
        uint256 claimedAmount,
        uint256 reportTimestamp,
        uint256 nonce,
        bytes calldata platformSignature
    ) external nonReentrant {
        require(!claimsPaused, "Claims paused");
        require(bytes(arweaveTxId).length > 0, "Invalid Arweave TX");
        require(claimedAmount > 0, "Amount must be > 0");
        require(
            block.timestamp >= lastClaimTimestamp[msg.sender] + MIN_CLAIM_COOLDOWN,
            "Claim cooldown active"
        );
        // The signed report must be fresh: not from the future, and not older than MAX_REPORT_AGE.
        require(reportTimestamp <= block.timestamp, "Report from the future");
        require(block.timestamp - reportTimestamp <= MAX_REPORT_AGE, "Report too old");

        // Verify platform signature (simple ECDSA for Phase 0/1)
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                msg.sender,
                arweaveTxId,
                claimedAmount,
                reportTimestamp,
                nonce,
                block.chainid
            )
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        address signer = recoverSigner(ethSignedMessageHash, platformSignature);
        require(signer == platformAttestor, "Invalid platform signature");

        // Consume-once: the identical signed report can never be claimed again.
        // Checked AFTER signature verification so an invalid signature cannot burn
        // someone else's valid report.
        require(!consumedReports[messageHash], "Report already claimed");
        consumedReports[messageHash] = true;

        // Apply tier multiplier (reuses existing MovieTicket tier logic)
        uint256 multiplier = getTierMultiplier(msg.sender); // 100 = 1.0x, 125 = 1.25x, 150 = 1.5x
        uint256 finalAmount = (claimedAmount * multiplier) / 100;

        credits[msg.sender] += finalAmount;
        lastClaimTimestamp[msg.sender] = block.timestamp;

        emit CreditsEarned(msg.sender, finalAmount, arweaveTxId, multiplier);
    }

    /**
     * @dev Redeem credits for perks (e.g. fee discount voucher, free ticket, Producer marker).
     * rewardType examples: "MINT_DISCOUNT_10", "FREE_BURNABLE_TICKET", "PRODUCER_ELIGIBLE"
     */
    function redeemCredits(uint256 amount, bytes32 rewardType) external nonReentrant {
        require(amount > 0 && credits[msg.sender] >= amount, "Insufficient credits");

        credits[msg.sender] -= amount;

        // Future: actually mint vouchers or interact with MovieTicket
        // For Phase 0/1 we just emit the event (frontend/off-chain applies the perk)
        emit CreditsRedeemed(msg.sender, amount, rewardType);
    }

    /**
     * @dev Returns tier multiplier for a user based on their highest owned MovieTicket tier.
     * Reuses the same scan pattern as hasAccessToVideo for consistency in Phase 0.
     */
    function getTierMultiplier(address user) public view returns (uint256) {
        // Real tier bonus from the user's highest owned MovieTicket tier (O(1), no scan):
        // 150 = 1.5x (Producer), 125 = 1.25x (Deluxe), 100 = 1.0x (Basic / none).
        return movieTicket.highestTierMultiplier(user);
    }

    // Internal ECDSA recovery (standard)
    function recoverSigner(bytes32 hash, bytes memory signature) internal pure returns (address) {
        require(signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid v");
        return ecrecover(hash, v, r, s);
    }

    // Emergency / admin (owner only)
    function emergencySlash(address seeder, uint256 amount) external onlyOwner {
        if (credits[seeder] >= amount) {
            credits[seeder] -= amount;
        }
    }

    event ClaimsPauseToggled(bool paused);

    function pauseClaims() external onlyOwner {
        claimsPaused = true;
        emit ClaimsPauseToggled(true);
    }

    function unpauseClaims() external onlyOwner {
        claimsPaused = false;
        emit ClaimsPauseToggled(false);
    }
}

contracts/SeederReputation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SeederReputation
 * @author Decentralflix — Phase 2 (step 6)
 * @notice On-chain seeder reputation ledger fed by a trusted attestor.
 *
 * A platform attestor (owner-set; same trust pattern as `SeederCredits`)
 * submits periodic seeding reports per seeder. Reports accumulate into
 * lifetime totals, and {scoreOf} computes a reputation score on-chain from a
 * documented formula.
 *
 * SCORING FORMULA:
 *   score = (uptimeSecs / 3600) + (bytesServed / 1e9) * 10 + validProofs * 100
 * i.e. 1 point per hour of reported seeding uptime, 10 points per reported
 * gigabyte served, 100 points per reported valid proof. All division is
 * integer division (remainders are dropped). A seeder with no reports scores 0.
 *
 * ═══════════════════════════════════════════════════════════════════════
 * LIMITATIONS — READ BEFORE USING SCORES FOR ANYTHING THAT MATTERS:
 * - Scores reflect ATTESTOR-REPORTED DATA, not independently verified facts.
 *   The attestor is a trusted party; a compromised or dishonest attestor can
 *   fabricate arbitrary scores.
 * - Scores are NOT Sybil-proof. A single entity can run many seeder
 *   identities and accumulate score across all of them.
 * - Self-dealing is undetectable here: a seeder serving its own requests
 *   looks identical to a seeder serving real demand.
 * - Treat scores as INFORMATIONAL ONLY. Do not gate payouts, access, or
 *   rewards on them without an additional verification layer (e.g.
 *   challenge-response proofs, stake-weighted identity, or decentralized
 *   attestation). See `docs/REPUTATION_LIMITATIONS.md` for the full analysis.
 * ═══════════════════════════════════════════════════════════════════════
 *
 * @dev `periodId` is recorded in the event log for off-chain accounting only;
 * the contract does not deduplicate reports per period — the attestor is
 * trusted not to double-report. If that assumption ever changes, add
 * per-(seeder, periodId) replay protection.
 */
contract SeederReputation is Ownable {
    /// @notice Lifetime accumulated seeding stats for one seeder identity.
    struct Stats {
        uint64 uptimeSecs; // total reported seeding uptime in seconds
        uint128 bytesServed; // total reported bytes served
        uint64 validProofs; // total reported valid proofs (e.g. fragment proofs)
        uint64 reportCount; // number of reports ever submitted
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error NotAttestor(address caller);
    error InvalidAttestor();
    error InvalidSeeder();

    // ── Events ────────────────────────────────────────────────────────────
    event AttestorUpdated(address indexed oldAttestor, address indexed newAttestor);
    event SeedingReported(
        address indexed seeder,
        uint64 indexed periodId,
        uint64 uptimeSecs,
        uint128 bytesServed,
        uint64 validProofs
    );

    /// @notice The trusted attestor allowed to submit seeding reports.
    address public attestor;

    mapping(address => Stats) private _stats; // seeder => Stats

    constructor() Ownable(msg.sender) {
        attestor = msg.sender; // owner starts as attestor (bootstrap, like SeederCredits)
    }

    /**
     * @notice Rotate the attestor. Only the contract owner may do this.
     * @param newAttestor Address of the new attestor (must be non-zero).
     */
    function setAttestor(address newAttestor) external onlyOwner {
        if (newAttestor == address(0)) revert InvalidAttestor();
        address old = attestor;
        attestor = newAttestor;
        emit AttestorUpdated(old, newAttestor);
    }

    /**
     * @notice Submit a seeding report for one period. Attestor-only.
     * Totals accumulate; reports are never overwritten.
     * @param seeder The seeder identity being reported on.
     * @param uptimeSecs Reported seeding uptime for the period, in seconds.
     * @param bytesServed Reported bytes served for the period.
     * @param validProofs Reported valid proofs for the period.
     * @param periodId Attestor-defined period identifier (accounting only;
     * not deduplicated on-chain).
     */
    function reportSeeding(
        address seeder,
        uint64 uptimeSecs,
        uint128 bytesServed,
        uint64 validProofs,
        uint64 periodId
    ) external {
        if (msg.sender != attestor) revert NotAttestor(msg.sender);
        if (seeder == address(0)) revert InvalidSeeder();

        Stats storage s = _stats[seeder];
        s.uptimeSecs += uptimeSecs;
        s.bytesServed += bytesServed;
        s.validProofs += validProofs;
        s.reportCount += 1;

        emit SeedingReported(seeder, periodId, uptimeSecs, bytesServed, validProofs);
    }

    /**
     * @notice Compute the reputation score for a seeder from accumulated stats.
     * Formula: (uptimeSecs / 3600) + (bytesServed / 1e9) * 10 + validProofs * 100.
     * @dev Informational only — see the limitations notice above.
     * @param seeder The seeder identity.
     * @return The score as a uint256 (0 for a seeder with no reports).
     */
    function scoreOf(address seeder) public view returns (uint256) {
        Stats storage s = _stats[seeder];
        return (uint256(s.uptimeSecs) / 3600)
            + (uint256(s.bytesServed) / 1_000_000_000) * 10
            + uint256(s.validProofs) * 100;
    }

    /**
     * @notice Return the accumulated stats for a seeder.
     * @param seeder The seeder identity.
     */
    function getStats(address seeder)
        external
        view
        returns (uint64 uptimeSecs, uint128 bytesServed, uint64 validProofs, uint64 reportCount)
    {
        Stats storage s = _stats[seeder];
        return (s.uptimeSecs, s.bytesServed, s.validProofs, s.reportCount);
    }
}

contracts/SubscriptionManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./RevenueSplitter.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SubscriptionManager
 * @author Decentralflix — Phase 2
 * @notice Time-based recurring access passes. The owner creates plans
 * (name, price, duration, creator); users subscribe with exact payment, renew
 * an active subscription to extend it, or cancel to end it immediately (no
 * refunds).
 * @notice NON-CUSTODIAL SPLITTER: every payment is split immediately through
 * the shared RevenueSplitter — 75% to the plan's creator, 25% to the platform
 * (owner). The split is an immutable constant; the owner cannot change it,
 * and the plan creator cannot be changed after creation, so funds can never
 * be redirected. No subscription balance accrues in the contract.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 * NOTE: this contract is unaudited.
 */
contract SubscriptionManager is RevenueSplitter, ReentrancyGuard {
    /// @notice A purchasable access plan.
    struct Plan {
        string name; // plan display name
        uint256 priceWei; // exact subscription/renewal price in wei
        uint256 durationSecs; // how long one purchase lasts
        address creator; // set once at creation; receives the 75% creator share. Immutable.
        bool active; // false => new subscriptions/renewals blocked
        bool exists; // creation guard
    }

    /// @notice One user's current subscription state.
    struct Subscription {
        uint256 planId; // plan the subscription is on
        uint256 expiresAt; // unix timestamp; active while > block.timestamp
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error PlanAlreadyExists(uint256 planId);
    error PlanNotFound(uint256 planId);
    error PlanInactive(uint256 planId);
    error EmptyName();
    error ZeroPrice();
    error ZeroDuration();
    error IncorrectPayment(uint256 expected, uint256 received);
    error AlreadySubscribed(address holder);
    error SubscriptionNotActive(address holder);
    error PlanMismatch(uint256 currentPlanId, uint256 requestedPlanId);
    error NoSubscription(address holder);

    // ── Events ────────────────────────────────────────────────────────────
    event PlanCreated(
        uint256 indexed planId,
        string name,
        uint256 priceWei,
        uint256 durationSecs,
        address indexed creator
    );
    event PlanDeactivated(uint256 indexed planId);
    event Subscribed(
        address indexed holder,
        uint256 indexed planId,
        uint256 expiresAt,
        address indexed creator,
        uint256 creatorShare,
        uint256 platformFee
    );
    event Renewed(
        address indexed holder,
        uint256 indexed planId,
        uint256 newExpiresAt,
        address indexed creator,
        uint256 creatorShare,
        uint256 platformFee
    );
    event Cancelled(address indexed holder, uint256 indexed planId);

    mapping(uint256 => Plan) private _plans; // planId => Plan
    mapping(address => Subscription) private _subscriptions; // holder => Subscription

    constructor() Ownable(msg.sender) {}

    // ── Plan management (owner only) ──────────────────────────────────────

    /**
     * @notice Create a subscription plan. The creator address is set ONCE here
     * and can never be changed — the owner cannot redirect the creator's share
     * later. Reverts if the creator is the zero address.
     * @param planId Platform-unique plan identifier (must be unused).
     * @param name Plan display name (non-empty).
     * @param priceWei Exact price per subscription period in wei (must be > 0).
     * @param durationSecs Length of one subscription period in seconds (must be > 0).
     * @param creator Address receiving the 75% creator share of every payment.
     */
    function createPlan(
        uint256 planId,
        string calldata name,
        uint256 priceWei,
        uint256 durationSecs,
        address creator
    ) external onlyOwner {
        if (_plans[planId].exists) revert PlanAlreadyExists(planId);
        if (bytes(name).length == 0) revert EmptyName();
        if (priceWei == 0) revert ZeroPrice();
        if (durationSecs == 0) revert ZeroDuration();
        if (creator == address(0)) revert MissingCreator();

        _plans[planId] = Plan({
            name: name,
            priceWei: priceWei,
            durationSecs: durationSecs,
            creator: creator,
            active: true,
            exists: true
        });

        emit PlanCreated(planId, name, priceWei, durationSecs, creator);
    }

    /**
     * @notice Deactivate a plan. Existing active subscriptions keep working until
     * they expire, but new subscriptions and renewals are blocked.
     * @dev Deactivation moves no funds and cannot redirect them.
     */
    function deactivatePlan(uint256 planId) external onlyOwner {
        Plan storage plan = _getPlanOrRevert(planId);
        plan.active = false;
        emit PlanDeactivated(planId);
    }

    // ── Subscriptions ─────────────────────────────────────────────────────

    /**
     * @notice Start a subscription. Requires no currently active subscription
     * (cancel or let it expire first) and exact payment of the plan price.
     * The payment is split immediately: 25% to the platform, 75% (+ rounding
     * remainder) to the plan's creator.
     */
    function subscribe(uint256 planId) external payable nonReentrant {
        Plan memory plan = _getPlanOrRevert(planId);
        if (!plan.active) revert PlanInactive(planId);
        if (hasActiveSubscription(msg.sender)) revert AlreadySubscribed(msg.sender);
        if (msg.value != plan.priceWei) revert IncorrectPayment(plan.priceWei, msg.value);

        uint256 expiresAt = block.timestamp + plan.durationSecs;
        _subscriptions[msg.sender] = Subscription({planId: planId, expiresAt: expiresAt});

        (uint256 creatorShare, uint256 platformFee) = _splitPayment(plan);

        emit Subscribed(msg.sender, planId, expiresAt, plan.creator, creatorShare, platformFee);
    }

    /**
     * @notice Extend an active subscription by one plan period. Must be called
     * while the subscription is still active and for the same plan the
     * subscription is on. The payment is split immediately, as in subscribe().
     */
    function renew(uint256 planId) external payable nonReentrant {
        Subscription storage sub = _subscriptions[msg.sender];
        if (sub.expiresAt <= block.timestamp) revert SubscriptionNotActive(msg.sender);
        if (sub.planId != planId) revert PlanMismatch(sub.planId, planId);

        Plan memory plan = _getPlanOrRevert(planId);
        if (!plan.active) revert PlanInactive(planId);
        if (msg.value != plan.priceWei) revert IncorrectPayment(plan.priceWei, msg.value);

        sub.expiresAt += plan.durationSecs;

        (uint256 creatorShare, uint256 platformFee) = _splitPayment(plan);

        emit Renewed(msg.sender, planId, sub.expiresAt, plan.creator, creatorShare, platformFee);
    }

    /**
     * @notice End the caller's subscription immediately. No refund is issued;
     * already-paid time is forfeited.
     */
    function cancel() external {
        if (!hasActiveSubscription(msg.sender)) revert NoSubscription(msg.sender);
        uint256 planId = _subscriptions[msg.sender].planId;
        _subscriptions[msg.sender].expiresAt = block.timestamp;
        emit Cancelled(msg.sender, planId);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice True if `holder` has a subscription with `expiresAt > block.timestamp`.
    function hasActiveSubscription(address holder) public view returns (bool) {
        return _subscriptions[holder].expiresAt > block.timestamp;
    }

    /// @notice Returns the plan ID and expiry timestamp of `holder`'s subscription.
    function subscriptionOf(address holder)
        external
        view
        returns (uint256 planId, uint256 expiresAt)
    {
        Subscription memory sub = _subscriptions[holder];
        return (sub.planId, sub.expiresAt);
    }

    /// @notice Full metadata for a plan. Reverts if the plan does not exist.
    function getPlan(uint256 planId) external view returns (Plan memory) {
        return _getPlanOrRevert(planId);
    }

    /**
     * @notice Split the plan payment 75/25 through the shared RevenueSplitter.
     * Reverts on a zero creator — the creator's share is NEVER redirected to
     * the owner.
     * @return creatorShare wei sent to the plan's creator.
     * @return platformFee wei sent to the platform (owner).
     */
    function _splitPayment(Plan memory plan)
        internal
        returns (uint256 creatorShare, uint256 platformFee)
    {
        return _splitRevenue(plan.creator);
    }

    function _getPlanOrRevert(uint256 planId) internal view returns (Plan storage) {
        Plan storage plan = _plans[planId];
        if (!plan.exists) revert PlanNotFound(planId);
        return plan;
    }
}

contracts/TicketNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "./RevenueSplitter.sol";

/**
 * @title TicketNFT
 * @author Decentralflix — Phase 2
 * @notice ERC721 movie tickets. Each film is registered once by the platform owner;
 * buyers mint single tickets by paying the film's exact price, which is split
 * 75/25 at purchase through the shared RevenueSplitter (75% + rounding remainder
 * to the filmmaker, 25% to the platform). Tickets are transferable by default, but a film can be
 * flagged `soulbound` at registration to make its tickets non-transferable
 * (mint and burn still work). A ticket is single-use: `redeemTicket` burns it on
 * entry, after which `hasValidTicket` returns false.
 * @dev Utility/access tokens only. No investment contract, no promised returns.
 * Any mainnet deployment must be reviewed by licensed counsel first.
 */
contract TicketNFT is ERC721, RevenueSplitter, ReentrancyGuard {
    using Strings for uint256;

    /// @notice Metadata for one registered film.
    struct Film {
        string title; // human-readable title
        uint256 priceWei; // exact mint price in wei (0 = free film)
        address filmmaker; // receives mint payments
        bool active; // false => minting disabled (redemption still works)
        bool soulbound; // true => tickets cannot be transferred
        string metadataURI; // base URI used to build tokenURI
        bool exists; // registration guard
    }

    // ── Errors ────────────────────────────────────────────────────────────
    error InvalidFilmId();
    error FilmAlreadyRegistered(uint256 filmId);
    error FilmNotFound(uint256 filmId);
    error FilmInactive(uint256 filmId);
    error EmptyTitle();
    error ZeroAddress();
    error IncorrectPayment(uint256 expected, uint256 received);
    error SoulboundTransferBlocked(uint256 tokenId);
    error NotTicketOwner(uint256 tokenId, address caller);

    // ── Events ────────────────────────────────────────────────────────────
    event FilmRegistered(
        uint256 indexed filmId,
        string title,
        uint256 priceWei,
        address indexed filmmaker,
        bool soulbound
    );
    event FilmStatusChanged(uint256 indexed filmId, bool active);
    event FilmPriceUpdated(uint256 indexed filmId, uint256 oldPrice, uint256 newPrice);
    event TicketMinted(
        uint256 indexed tokenId,
        uint256 indexed filmId,
        address indexed buyer,
        uint256 pricePaid
    );
    event TicketRedeemed(uint256 indexed tokenId, uint256 indexed filmId, address indexed holder);

    uint256 private _nextTokenId = 1;

    mapping(uint256 => Film) private _films; // filmId => Film
    mapping(uint256 => uint256) private _ticketFilm; // tokenId => filmId
    mapping(uint256 => mapping(address => uint256)) private _validTickets; // filmId => holder => unredeemed count

    constructor() ERC721("Decentralflix Ticket", "DFLIX-TIX") Ownable(msg.sender) {}

    // ── Film registry (owner only) ────────────────────────────────────────

    /**
     * @notice Register a film so tickets can be minted for it.
     * @param filmId Platform-unique film identifier (must be non-zero and unused).
     * @param title Film title (non-empty).
     * @param priceWei Exact ticket price in wei (0 allowed for free films).
     * @param filmmaker Address that receives mint payments (non-zero).
     * @param soulbound If true, tickets for this film cannot be transferred.
     * @param metadataURI Base URI for token metadata (may be empty).
     */
    function registerFilm(
        uint256 filmId,
        string calldata title,
        uint256 priceWei,
        address filmmaker,
        bool soulbound,
        string calldata metadataURI
    ) external onlyOwner {
        if (filmId == 0) revert InvalidFilmId();
        if (_films[filmId].exists) revert FilmAlreadyRegistered(filmId);
        if (bytes(title).length == 0) revert EmptyTitle();
        if (filmmaker == address(0)) revert ZeroAddress();

        _films[filmId] = Film({
            title: title,
            priceWei: priceWei,
            filmmaker: filmmaker,
            active: true,
            soulbound: soulbound,
            metadataURI: metadataURI,
            exists: true
        });

        emit FilmRegistered(filmId, title, priceWei, filmmaker, soulbound);
    }

    /**
     * @notice Enable or disable minting for a film. Redemption of already-minted
     * tickets is unaffected.
     */
    function setFilmActive(uint256 filmId, bool active) external onlyOwner {
        Film storage film = _getFilmOrRevert(filmId);
        film.active = active;
        emit FilmStatusChanged(filmId, active);
    }

    /// @notice Update a film's ticket price. Does not affect already-minted tickets.
    function setFilmPrice(uint256 filmId, uint256 newPrice) external onlyOwner {
        Film storage film = _getFilmOrRevert(filmId);
        uint256 oldPrice = film.priceWei;
        film.priceWei = newPrice;
        emit FilmPriceUpdated(filmId, oldPrice, newPrice);
    }

    // ── Minting / redemption ──────────────────────────────────────────────

    /**
     * @notice Mint one ticket for `filmId`. Requires exact payment of the film's
     * current price; the payment is split 75/25 at purchase through the shared
     * RevenueSplitter (75% + rounding remainder to the filmmaker, 25% platform).
     * Reverts on a zero filmmaker — the filmmaker's share is NEVER redirected.
     * @return tokenId The newly minted ticket's token ID.
     */
    function mintTicket(uint256 filmId) external payable nonReentrant returns (uint256 tokenId) {
        Film memory film = _getFilmOrRevert(filmId);
        if (!film.active) revert FilmInactive(filmId);
        if (msg.value != film.priceWei) revert IncorrectPayment(film.priceWei, msg.value);

        tokenId = _nextTokenId;
        _nextTokenId += 1;

        _ticketFilm[tokenId] = filmId;
        _validTickets[filmId][msg.sender] += 1;
        _safeMint(msg.sender, tokenId);

        emit TicketMinted(tokenId, filmId, msg.sender, msg.value);

        // Split the mint payment 75/25 through the shared RevenueSplitter.
        // Exact payment is enforced above, so nothing can accrue in the contract.
        // Free films (price 0) skip the transfers entirely.
        if (msg.value > 0) {
            _splitRevenue(film.filmmaker);
        }
    }

    /**
     * @notice Burn a ticket on entry. Only the ticket's current owner can redeem.
     * A redeemed ticket no longer counts toward `hasValidTicket`.
     */
    function redeemTicket(uint256 tokenId) external nonReentrant {
        address owner = _requireOwned(tokenId);
        if (owner != msg.sender) revert NotTicketOwner(tokenId, msg.sender);

        uint256 filmId = _ticketFilm[tokenId];
        _burn(tokenId);
        _validTickets[filmId][owner] -= 1;

        emit TicketRedeemed(tokenId, filmId, owner);
    }

    // ── Views ─────────────────────────────────────────────────────────────

    /// @notice True if `holder` owns at least one unredeemed ticket for `filmId`.
    function hasValidTicket(address holder, uint256 filmId) external view returns (bool) {
        return _validTickets[filmId][holder] > 0;
    }

    /// @notice Number of unredeemed tickets `holder` owns for `filmId`.
    function validTicketCount(address holder, uint256 filmId) external view returns (uint256) {
        return _validTickets[filmId][holder];
    }

    /// @notice The film a ticket was minted for.
    function ticketFilm(uint256 tokenId) external view returns (uint256) {
        _requireOwned(tokenId);
        return _ticketFilm[tokenId];
    }

    /// @notice Full metadata for a registered film. Reverts if unregistered.
    function getFilm(uint256 filmId) external view returns (Film memory) {
        return _getFilmOrRevert(filmId);
    }

    /// @notice Next token ID that will be minted (informational).
    function nextTokenId() external view returns (uint256) {
        return _nextTokenId;
    }

    /**
     * @dev Builds `<metadataURI>/<tokenId>` when the film registered a base URI,
     * otherwise returns an empty string.
     */
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        string memory base = _films[_ticketFilm[tokenId]].metadataURI;
        if (bytes(base).length == 0) return "";
        return string.concat(base, "/", tokenId.toString());
    }

    // ── Soulbound enforcement ─────────────────────────────────────────────

    /**
     * @dev Blocks transfers (not mints or burns) for films flagged soulbound.
     * @param to Recipient; `address(0)` on burn, `from` is `address(0)` on mint.
     */
    function _update(address to, uint256 tokenId, address auth)
        internal
        override
        returns (address)
    {
        address from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0)) {
            uint256 filmId = _ticketFilm[tokenId];
            if (_films[filmId].soulbound) {
                revert SoulboundTransferBlocked(tokenId);
            }
            // Keep the per-holder valid-ticket counts in sync with transfers.
            address newOwner = super._update(to, tokenId, auth);
            _validTickets[filmId][from] -= 1;
            _validTickets[filmId][to] += 1;
            return newOwner;
        }
        return super._update(to, tokenId, auth);
    }

    function _getFilmOrRevert(uint256 filmId) internal view returns (Film storage) {
        Film storage film = _films[filmId];
        if (!film.exists) revert FilmNotFound(filmId);
        return film;
    }
}

